from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination.

    Coins of different denominations are never combined. The input is not
    modified. Binary search uses inclusion-exclusion to count distinct amounts
    without enumerating them, so even very large values of k are supported.
    """
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    upper = denominations[0] * k
    # Coefficients combine subset terms with the same least common multiple.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for divisor, coefficient in coefficients.items():
            intersection = lcm(divisor, coin)
            if intersection <= upper:
                changes[intersection] = changes.get(intersection, 0) - coefficient
        for divisor, change in changes.items():
            coefficient = coefficients.get(divisor, 0) + change
            if coefficient:
                coefficients[divisor] = coefficient
            else:
                coefficients.pop(divisor, None)

    # Terms above the search bound contribute zero to every count.
    terms = [(divisor, coefficient)
             for divisor, coefficient in coefficients.items()
             if divisor <= upper]
    lower = k  # The k-th distinct positive integer cannot be less than k.
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum((middle // divisor) * coefficient
                    for divisor, coefficient in terms)
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower
